// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------
try {
  while (running) archStep();
} catch (e) {
  process.stderr.write('\nvm.js: ' + e.message + '\n');
  if (process.env.VM_DEBUG) process.stderr.write(e.stack + '\n');
  process.exitCode = 1;
}

