function wr16(a, v) {
  a >>>= 0;
  mem[a] = v; mem[a + 1] = v >>> 8;
}
function wr32(a, v) {
  a >>>= 0;
  mem[a] = v; mem[a + 1] = v >>> 8; mem[a + 2] = v >>> 16; mem[a + 3] = v >>> 24;
}
