  }
}

// Node lacks lseekSync: track offsets ourselves.
const fdPos = new Map();
function posixLseek(hfd, off, whence) {
  let base = 0;
  if (whence === SEEK_CUR) base = fdPos.get(hfd) || 0;
  else if (whence === SEEK_END) base = fs.fstatSync(hfd).size;
  const pos = base + off;
  fdPos.set(hfd, pos);
  return pos;
}

// ---------------------------------------------------------------------------
// Interpreter
// ---------------------------------------------------------------------------
let pc = entry >>> 0;
let pendingBranch = -1;

function archStep() {
  const cur = pc;
  const instr = mem32[cur >>> 2];
  pc = (cur + 4) >>> 0;
  let branchTo = -1;

  const op = instr >>> 26;
  const rs = (instr >>> 21) & 31;
  const rt = (instr >>> 16) & 31;
  const rd = (instr >>> 11) & 31;
  const sa = (instr >>> 6) & 31;
  const funct = instr & 63;
  const imm = instr & 0xffff;
  const simm = (imm << 16) >> 16;

  switch (op) {
    case 0: // SPECIAL
      switch (funct) {
        case 0x00: reg[rd] = reg[rt] << sa; break;
        case 0x02:
