#!/usr/bin/env node
'use strict';

// Minimal MIPS32 (little endian, o32) userspace emulator for doomgeneric_mips.
// System calls use the Linux x86_64 syscall numbers selected in my_stdlib.c.

const fs = require('fs');
const path = require('path');

const ELF_FILE = path.join(__dirname, 'doomgeneric_mips');

// ---------------------------------------------------------------------------
// ELF loading
// ---------------------------------------------------------------------------
const elf = fs.readFileSync(ELF_FILE);
if (elf.readUInt32BE(0) !== 0x7f454c46) throw new Error('not an ELF file');
if (elf[4] !== 1 || elf[5] !== 1) throw new Error('expected ELF32 little endian');

const phoff = elf.readUInt32LE(28);
const phentsize = elf.readUInt16LE(42);
const phnum = elf.readUInt16LE(44);
const entry = elf.readUInt32LE(24);

// Doom's static 1 GiB heap lives in .bss, so the address space is large but
// sparsely used.  Keep a flat 1.09 GiB zero-filled array: Linux commits only
// pages that are actually touched.
const MEM_SIZE = 0x41000000;
const memBuf = new ArrayBuffer(MEM_SIZE);
const mem = new Uint8Array(memBuf);
const mem32 = new Uint32Array(memBuf);

let loadedEnd = 0;
for (let i = 0; i < phnum; i++) {
  const off = phoff + i * phentsize;
  if (elf.readUInt32LE(off) !== 1) continue; // PT_LOAD
  const foff = elf.readUInt32LE(off + 4);
  const vaddr = elf.readUInt32LE(off + 8);
  const filesz = elf.readUInt32LE(off + 16);
  const memsz = elf.readUInt32LE(off + 20);
  elf.copy(mem, vaddr, foff, foff + filesz);
  loadedEnd = Math.max(loadedEnd, vaddr + memsz);
}

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------
const reg = new Int32Array(32);
const freg = new Uint32Array(32);
const f32 = new Float32Array(freg.buffer);
const dscratch = new ArrayBuffer(8);
const dview = new DataView(dscratch);
const d64 = new Float64Array(dscratch);
const i64 = new BigInt64Array(dscratch);

let hi = 0, lo = 0;
let fcc0 = false;
let running = true;
let insnCount = 0;
const maxInsns = parseInt(process.env.VM_MAX_INSNS || '0', 10) || 0;

const STACK_TOP = 0x40f00000;
reg[29] = STACK_TOP | 0; // sp
reg[28] = 0x0047d090 | 0; // gp
reg[31] = 0; // ra

// ---------------------------------------------------------------------------
// Memory helpers (little endian)
// ---------------------------------------------------------------------------
function rd8(a) { return mem[a >>> 0]; }
function rd16(a) {
  a >>>= 0;
  return mem[a] | (mem[a + 1] << 8);
}
function rd32(a) {
  a >>>= 0;
  return (mem[a] | (mem[a + 1] << 8) | (mem[a + 2] << 16) | (mem[a + 3] << 24)) | 0;
}
function wr8(a, v) { mem[a >>> 0] = v; }
function wr16(a, v) {
  a >>>= 0;
  mem[a] = v; mem[a + 1] = v >>> 8;
}
function wr32(a, v) {
  a >>>= 0;
  mem[a] = v; mem[a + 1] = v >>> 8; mem[a + 2] = v >>> 16; mem[a + 3] = v >>> 24;
}
function readCString(a) {
  a >>>= 0;
  let s = '';
  while (mem[a] !== 0) {
    s += String.fromCharCode(mem[a]);
    a++;
  }
  return s;
}
function getD(i) {
  dview.setUint32(0, freg[i], true);
  dview.setUint32(4, freg[i + 1], true);
  return d64[0];
}
function setD(i, v) {
  d64[0] = v;
  freg[i] = dview.getUint32(0, true);
  freg[i + 1] = dview.getUint32(4, true);
}

// ---------------------------------------------------------------------------
// System calls
// ---------------------------------------------------------------------------
const fdMap = new Map(); // guest fd -> host fd
for (const fd of [0, 1, 2]) fdMap.set(fd, fd);
let nextFd = 3;
const SEEK_SET = 0, SEEK_CUR = 1, SEEK_END = 2;

function syscall(num, a0, a1, a2, a3, a4, a5) {
  switch (num) {
    case 0: { // read
      if (a0 === 0) return 0;
      const hfd = fdMap.get(a0);
      if (hfd === undefined) return -9;
      try {
        const buf = Buffer.alloc(a2);
        const n = fs.readSync(hfd, buf, 0, a2, null);
        buf.copy(mem, a1 >>> 0, 0, n);
        return n;
      } catch (e) { return -e.errno || -5; }
    }
    case 1: { // write
      const hfd = fdMap.get(a0);
      if (hfd === undefined) return -9;
      const data = Buffer.from(memBuf, a1 >>> 0, a2);
      try {
        if (hfd === 1) { process.stdout.write(data); return a2; }
        if (hfd === 2) { process.stderr.write(data); return a2; }
        return fs.writeSync(hfd, data, 0, a2);
      } catch (e) { return -e.errno || -5; }
    }
    case 2: { // open
      const name = readCString(a0);
      let flags = a1 & 3;
      let f = flags === 0 ? fs.constants.O_RDONLY :
              flags === 1 ? fs.constants.O_WRONLY : fs.constants.O_RDWR;
      if (a1 & 64) f |= fs.constants.O_CREAT;
      if (a1 & 128) f |= fs.constants.O_EXCL;
      if (a1 & 512) f |= fs.constants.O_TRUNC;
      if (a1 & 1024) f |= fs.constants.O_APPEND;
      try {
        const hfd = fs.openSync(name, f, a2 & 0x1ff);
        const gfd = nextFd++;
        fdMap.set(gfd, hfd);
        return gfd;
      } catch (e) {
        return -(e.errno || 2);
      }
    }
    case 3: { // close
      const hfd = fdMap.get(a0);
      if (hfd === undefined) return -9;
      try { fs.closeSync(hfd); } catch (e) { return -(e.errno || 9); }
      fdMap.delete(a0);
      return 0;
    }
    case 8: { // lseek
      const hfd = fdMap.get(a0);
      if (hfd === undefined) return -9;
      try {
        return fs.lseekSync ? fs.lseekSync(hfd, a1, a2) : (() => {
          // Node has no lseekSync; emulate position with read/write positions
          return posixLseek(hfd, a1, a2);
        })();
      } catch (e) { return -(e.errno || 9); }
    }
    case 35: return 0; // nanosleep
    case 60: { running = false; return 0; } // exit
    case 74: return 0; // fsync
    case 82: { // rename
      try { fs.renameSync(readCString(a0), readCString(a1)); return 0; }
      catch (e) { return -(e.errno || 2); }
    }
    case 83: { // mkdir
      try { fs.mkdirSync(readCString(a0), { mode: a1 & 0x1ff }); return 0; }
      catch (e) { return -(e.errno || 17); }
    }
    case 87: { // unlink
      try { fs.unlinkSync(readCString(a0)); return 0; }
      catch (e) { return -(e.errno || 2); }
    }
    case 96: { // gettimeofday
      if (a0) { const t = Date.now() / 1000; wr32(a0, Math.floor(t)); wr32(a0 + 4, Math.floor((t % 1) * 1e6)); }
      return 0;
    }
    case 201: { // time
      const t = Math.floor(Date.now() / 1000);
      if (a0) wr32(a0, t);
      return t;
    }
    default:
      return -38; // ENOSYS
  }
}

// Node lacks lseekSync: track offsets ourselves.
const fdPos = new Map();
function posixLseek(hfd, off, whence) {
  let base = 0;
  if (whence === SEEK_CUR) base = fdPos.get(hfd) || 0;
  else if (whence === SEEK_END) base = fs.fstatSync(hfd).size;
  const pos = base + off;
  fdPos.set(hfd, pos);
  return pos;
}

// ---------------------------------------------------------------------------
// Interpreter
// ---------------------------------------------------------------------------
let pc = entry >>> 0;
let pendingBranch = -1;

function archStep() {
  const cur = pc;
  const instr = mem32[cur >>> 2];
  pc = (cur + 4) >>> 0;
  let branchTo = -1;

  const op = instr >>> 26;
  const rs = (instr >>> 21) & 31;
  const rt = (instr >>> 16) & 31;
  const rd = (instr >>> 11) & 31;
  const sa = (instr >>> 6) & 31;
  const funct = instr & 63;
  const imm = instr & 0xffff;
  const simm = (imm << 16) >> 16;

  switch (op) {
    case 0: // SPECIAL
      switch (funct) {
        case 0x00: reg[rd] = reg[rt] << sa; break;
        case 0x02:
          if (rs === 0) reg[rd] = reg[rt] >>> sa;
          else { const s = sa & 31; reg[rd] = s === 0 ? reg[rt] : ((reg[rt] >>> s) | (reg[rt] << (32 - s))); }
          break;
        case 0x03: reg[rd] = reg[rt] >> sa; break;
        case 0x04: { const s = reg[rs] & 31; reg[rd] = reg[rt] << s; break; }
        case 0x06:
          if (sa === 0) { const s = reg[rs] & 31; reg[rd] = reg[rt] >>> s; }
          else { const s = reg[rs] & 31; reg[rd] = s === 0 ? reg[rt] : ((reg[rt] >>> s) | (reg[rt] << (32 - s))); }
          break;
        case 0x07: { const s = reg[rs] & 31; reg[rd] = reg[rt] >> s; break; }
        case 0x08: branchTo = reg[rs] >>> 0; break; // jr
        case 0x09: reg[rd || 31] = (cur + 8) | 0; branchTo = reg[rs] >>> 0; break; // jalr
        case 0x0c: { // syscall
          const ret = syscall(reg[2] >>> 0, reg[4] >>> 0, reg[5] >>> 0, reg[6] >>> 0,
                              reg[7] >>> 0, reg[8] >>> 0, reg[9] >>> 0);
          reg[2] = ret | 0;
          break;
        }
        case 0x0d: throw new Error('break at 0x' + cur.toString(16));
        case 0x10: reg[rd] = hi; break;
        case 0x11: hi = reg[rs]; break;
        case 0x12: reg[rd] = lo; break;
        case 0x13: lo = reg[rs]; break;
        case 0x18: { const p = BigInt(reg[rs]) * BigInt(reg[rt]); i64[0] = p; lo = dview.getInt32(0, true); hi = dview.getInt32(4, true); break; }
        case 0x19: { const p = BigInt(reg[rs] >>> 0) * BigInt(reg[rt] >>> 0); i64[0] = BigInt.asIntN(64, p); lo = dview.getInt32(0, true); hi = dview.getInt32(4, true); break; }
        case 0x1a: {
          const a = reg[rs], b = reg[rt];
          if (b === 0) { lo = a >= 0 ? -1 : 1; hi = a; }
          else { lo = (a / b) | 0; hi = (a % b) | 0; }
          break;
        }
        case 0x1b: {
          const a = reg[rs] >>> 0, b = reg[rt] >>> 0;
          if (b === 0) { lo = -1; hi = a | 0; }
          else { lo = Math.floor(a / b) | 0; hi = (a % b) | 0; }
          break;
        }
        case 0x20: reg[rd] = (reg[rs] + reg[rt]) | 0; break;
        case 0x21: reg[rd] = (reg[rs] + reg[rt]) | 0; break;
        case 0x22: reg[rd] = (reg[rs] - reg[rt]) | 0; break;
        case 0x23: reg[rd] = (reg[rs] - reg[rt]) | 0; break;
        case 0x24: reg[rd] = reg[rs] & reg[rt]; break;
        case 0x25: reg[rd] = reg[rs] | reg[rt]; break;
        case 0x26: reg[rd] = reg[rs] ^ reg[rt]; break;
        case 0x27: reg[rd] = ~(reg[rs] | reg[rt]); break;
        case 0x2a: reg[rd] = reg[rs] < reg[rt] ? 1 : 0; break;
        case 0x2b: reg[rd] = (reg[rs] >>> 0) < (reg[rt] >>> 0) ? 1 : 0; break;
        case 0x34: if (reg[rs] === reg[rt]) throw new Error('trap teq at 0x' + cur.toString(16)); break;
        case 0x36: if (reg[rs] !== reg[rt]) throw new Error('trap tne at 0x' + cur.toString(16)); break;
        default: throw new Error('unimplemented SPECIAL funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
      }
      break;

    case 1: // REGIMM
      switch (rt) {
        case 0x00: if (reg[rs] < 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // bltz
        case 0x01: if (reg[rs] >= 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // bgez
        case 0x10: reg[31] = (cur + 8) | 0; if (reg[rs] < 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break;
        case 0x11: reg[31] = (cur + 8) | 0; if (reg[rs] >= 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break;
        default: throw new Error('unimplemented REGIMM rt=' + rt + ' at 0x' + cur.toString(16));
      }
      break;

    case 2: branchTo = (((cur + 4) & 0xf0000000) | ((instr & 0x03ffffff) << 2)) >>> 0; break; // j
    case 3: reg[31] = (cur + 8) | 0; branchTo = (((cur + 4) & 0xf0000000) | ((instr & 0x03ffffff) << 2)) >>> 0; break; // jal

    case 4: if (reg[rs] === reg[rt]) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // beq
    case 5: if (reg[rs] !== reg[rt]) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // bne
    case 6: if (reg[rs] <= 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // blez
    case 7: if (reg[rs] > 0) branchTo = (cur + 4 + (simm << 2)) >>> 0; break; // bgtz

    case 8: reg[rt] = (reg[rs] + simm) | 0; break; // addi
    case 9: reg[rt] = (reg[rs] + simm) | 0; break; // addiu
    case 10: reg[rt] = reg[rs] < simm ? 1 : 0; break; // slti
    case 11: reg[rt] = (reg[rs] >>> 0) < (simm >>> 0) ? 1 : 0; break; // sltiu
    case 12: reg[rt] = reg[rs] & imm; break; // andi
    case 13: reg[rt] = reg[rs] | imm; break; // ori
    case 14: reg[rt] = reg[rs] ^ imm; break; // xori
    case 15: reg[rt] = imm << 16; break; // lui

    case 0x1c: // SPECIAL2
      switch (funct) {
        case 0x02: reg[rd] = Math.imul(reg[rs], reg[rt]); break; // mul
        case 0x20: { let v = reg[rs] >>> 0, n = 0; while (v && !(v & 0x80000000)) { n++; v <<= 1; } reg[rd] = n; break; } // clz
        case 0x21: { let v = reg[rs] >>> 0, n = 0; while (v & 0x80000000) { n++; v <<= 1; } reg[rd] = n; break; } // clo
        default: throw new Error('unimplemented SPECIAL2 funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
      }
      break;

    case 0x1f: // SPECIAL3
      switch (funct) {
        case 0x00: { // ext
          const pos = sa, size = rd + 1;
          const mask = size === 32 ? 0xffffffff : ((1 << size) - 1);
          reg[rt] = ((reg[rs] >>> pos) & mask) | 0;
          break;
        }
        case 0x04: { // ins
          const pos = sa, size = rd - sa + 1;
          const mask = size === 32 ? 0xffffffff : ((1 << size) - 1);
          reg[rt] = (reg[rt] & ~(mask << pos)) | ((reg[rs] & mask) << pos);
          break;
        }
        case 0x20: // BSHFL
          if (sa === 0x02) reg[rd] = (((reg[rt] & 0xff) << 8) | ((reg[rt] >>> 8) & 0xff) |
                                      ((reg[rt] & 0xff0000) << 8) | ((reg[rt] >>> 8) & 0xff0000)) | 0; // wsbh
          else if (sa === 0x10) reg[rd] = (reg[rt] << 24) >> 24; // seb
          else if (sa === 0x18) reg[rd] = (reg[rt] << 16) >> 16; // seh
          else throw new Error('unimplemented BSHFL sa=' + sa);
          break;
        default: throw new Error('unimplemented SPECIAL3 funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
      }
      break;

    case 0x20: reg[rt] = (rd8(reg[rs] + simm) << 24) >> 24; break; // lb
    case 0x21: reg[rt] = (rd16(reg[rs] + simm) << 16) >> 16; break; // lh
    case 0x22: { // lwl
      const a = (reg[rs] + simm) >>> 0, k = a & 3, w = rd32(a & ~3);
      if (k === 0) reg[rt] = w;
      else if (k === 1) reg[rt] = (reg[rt] & 0xff) | (w << 8);
      else if (k === 2) reg[rt] = (reg[rt] & 0xffff) | (w << 16);
      else reg[rt] = (reg[rt] & 0xffffff) | (w << 24);
      break;
    }
    case 0x23: reg[rt] = rd32(reg[rs] + simm); break; // lw
    case 0x24: reg[rt] = rd8(reg[rs] + simm); break; // lbu
    case 0x25: reg[rt] = rd16(reg[rs] + simm); break; // lhu
    case 0x26: { // lwr
      const a = (reg[rs] + simm) >>> 0, k = a & 3, w = rd32(a & ~3);
      if (k === 0) reg[rt] = (reg[rt] & 0xffffff00) | (w & 0xff);
      else if (k === 1) reg[rt] = (reg[rt] & 0xffff0000) | (w & 0xffff);
      else if (k === 2) reg[rt] = (reg[rt] & 0xff000000) | (w & 0xffffff);
      else reg[rt] = w;
      break;
    }
    case 0x28: wr8(reg[rs] + simm, reg[rt]); break; // sb
    case 0x29: wr16(reg[rs] + simm, reg[rt]); break; // sh
    case 0x2a: { // swl
      const a = (reg[rs] + simm) >>> 0, k = a & 3, v = reg[rt];
      if (k === 0) wr32(a & ~3, v);
      else if (k === 1) { wr8((a & ~3) + 1, v >>> 24); wr8((a & ~3) + 2, v >>> 16); wr8((a & ~3) + 3, v >>> 8); }
      else if (k === 2) { wr8((a & ~3) + 2, v >>> 24); wr8((a & ~3) + 3, v >>> 16); }
      else wr8((a & ~3) + 3, v >>> 24);
      break;
    }
    case 0x2b: wr32(reg[rs] + simm, reg[rt]); break; // sw
    case 0x2e: { // swr
      const a = (reg[rs] + simm) >>> 0, k = a & 3, v = reg[rt];
      if (k === 0) wr8(a & ~3, v);
      else if (k === 1) { wr8((a & ~3), v); wr8((a & ~3) + 1, v >>> 8); }
      else if (k === 2) { wr8(a & ~3, v); wr8((a & ~3) + 1, v >>> 8); wr8((a & ~3) + 2, v >>> 16); }
      else wr32(a & ~3, v);
      break;
    }

    case 0x31: freg[rt] = rd32(reg[rs] + simm); break; // lwc1
    case 0x35: { // ldc1
      const a = reg[rs] + simm;
      freg[rt] = rd32(a); freg[rt + 1] = rd32(a + 4);
      break;
    }
    case 0x39: wr32(reg[rs] + simm, freg[rt]); break; // swc1
    case 0x3d: { // sdc1
      const a = reg[rs] + simm;
      wr32(a, freg[rt]); wr32(a + 4, freg[rt + 1]);
      break;
    }

    case 0x11: { // COP1
      switch (rs) {
        case 0x00: reg[rt] = freg[rd] | 0; break; // mfc1 (fs == rd)
        case 0x02: reg[rt] = 0; break; // cfc1
        case 0x04: freg[rd] = reg[rt]; break; // mtc1 (fs == rd)
        case 0x06: break; // ctc1
        case 0x07: freg[rd + 1] = reg[rt]; break; // mthc1
        case 0x08: { // bc1f / bc1t
          const taken = (rt & 1) ? fcc0 : !fcc0;
          if (taken) branchTo = (cur + 4 + (simm << 2)) >>> 0;
          break;
        }
        default: {
          const fmt = rs, ft = rt, fs = rd, fd = sa;
          if (fmt === 0x10) { // single
            switch (funct) {
              case 0x00: f32[fd] = f32[fs] + f32[ft]; break;
              case 0x01: f32[fd] = f32[fs] - f32[ft]; break;
              case 0x02: f32[fd] = f32[fs] * f32[ft]; break;
              case 0x03: f32[fd] = f32[fs] / f32[ft]; break;
              case 0x04: f32[fd] = Math.sqrt(f32[fs]); break;
              case 0x05: f32[fd] = Math.abs(f32[fs]); break;
              case 0x06: f32[fd] = f32[fs]; break;
              case 0x07: f32[fd] = -f32[fs]; break;
              case 0x0d: freg[fd] = Math.trunc(f32[fs]) | 0; break; // trunc.w.s
              case 0x0c: freg[fd] = Math.round(f32[fs]) | 0; break; // round.w.s
              case 0x0e: freg[fd] = Math.ceil(f32[fs]) | 0; break;
              case 0x0f: freg[fd] = Math.floor(f32[fs]) | 0; break;
              case 0x11: if (fcc0) f32[fd] = f32[fs]; break; // movt.s
              case 0x10: if (!fcc0) f32[fd] = f32[fs]; break; // movf.s
              case 0x21: setD(fd, f32[fs]); break; // cvt.d.s
              case 0x30: case 0x31: case 0x32: case 0x33:
              case 0x34: case 0x35: case 0x36: case 0x37:
              case 0x38: case 0x39: case 0x3a: case 0x3b:
              case 0x3c: case 0x3d: case 0x3e: case 0x3f: {
                const cond = funct & 0xf;
                const a = f32[fs], b = f32[ft];
                let r;
                switch (cond) {
                  case 2: r = a === b; break;              // eq
                  case 4: r = a < b; break;                // olt
                  case 6: r = a <= b; break;               // ole
                  case 12: r = !(a < b); break;            // lt (false if unordered)
                  case 14: r = !(a <= b); break;           // le
                  default: r = false;
                }
                fcc0 = !!r;
                break;
              }
              default: throw new Error('unimplemented COP1.S funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
            }
          } else if (fmt === 0x11) { // double
            switch (funct) {
              case 0x00: setD(fd, getD(fs) + getD(ft)); break;
              case 0x01: setD(fd, getD(fs) - getD(ft)); break;
              case 0x02: setD(fd, getD(fs) * getD(ft)); break;
              case 0x03: setD(fd, getD(fs) / getD(ft)); break;
              case 0x04: setD(fd, Math.sqrt(getD(fs))); break;
              case 0x05: setD(fd, Math.abs(getD(fs))); break;
              case 0x06: setD(fd, getD(fs)); break;
              case 0x07: setD(fd, -getD(fs)); break;
              case 0x11: if (fcc0) setD(fd, getD(fs)); break; // movt.d
              case 0x10: if (!fcc0) setD(fd, getD(fs)); break; // movf.d
              case 0x20: setD(fd, f32[fs]); break; // cvt.d.s (fmt should be s, handled below)
              case 0x21: f32[fd] = getD(fs); break; // cvt.s.d
              case 0x30: case 0x31: case 0x32: case 0x33:
              case 0x34: case 0x35: case 0x36: case 0x37:
              case 0x38: case 0x39: case 0x3a: case 0x3b:
              case 0x3c: case 0x3d: case 0x3e: case 0x3f: {
                const cond = funct & 0xf;
                const a = getD(fs), b = getD(ft);
                let r;
                switch (cond) {
                  case 2: r = a === b; break;
                  case 4: r = a < b; break;
                  case 6: r = a <= b; break;
                  case 12: r = !(a < b); break;
                  case 14: r = !(a <= b); break;
                  default: r = false;
                }
                fcc0 = !!r;
                break;
              }
              default: throw new Error('unimplemented COP1.D funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
            }
          } else if (fmt === 0x14) { // word
            switch (funct) {
              case 0x20: f32[fd] = freg[fs] | 0; break; // cvt.s.w
              case 0x21: setD(fd, freg[fs] | 0); break; // cvt.d.w
              default: throw new Error('unimplemented COP1.W funct 0x' + funct.toString(16) + ' at 0x' + cur.toString(16));
            }
          } else {
            throw new Error('unimplemented COP1 fmt ' + fmt + ' at 0x' + cur.toString(16));
          }
        }
      }
      break;
    }

    default:
      throw new Error('unimplemented opcode 0x' + op.toString(16) + ' at 0x' + cur.toString(16) +
                      ' instr 0x' + instr.toString(16));
  }

  reg[0] = 0;

  // Delay slot / branch handling.
  if (pendingBranch >= 0) {
    pc = pendingBranch >>> 0;
    pendingBranch = -1;
  } else if (branchTo >= 0) {
    pendingBranch = branchTo;
  }

  if (++insnCount >= maxInsns && maxInsns) running = false;
}

// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------
try {
  while (running) archStep();
} catch (e) {
  process.stderr.write('\nvm.js: ' + e.message + '\n');
  if (process.env.VM_DEBUG) process.stderr.write(e.stack + '\n');
  process.exitCode = 1;
}

