#!/usr/bin/env node
'use strict';

// Minimal MIPS32 (little endian, o32) userspace emulator for doomgeneric_mips.
// System calls use the Linux x86_64 syscall numbers selected in my_stdlib.c.

const fs = require('fs');
const path = require('path');

const ELF_FILE = path.join(__dirname, 'doomgeneric_mips');

// ---------------------------------------------------------------------------
// ELF loading
// ---------------------------------------------------------------------------
const elf = fs.readFileSync(ELF_FILE);
if (elf.readUInt32BE(0) !== 0x7f454c46) throw new Error('not an ELF file');
if (elf[4] !== 1 || elf[5] !== 1) throw new Error('expected ELF32 little endian');

const phoff = elf.readUInt32LE(28);
const phentsize = elf.readUInt16LE(42);
const phnum = elf.readUInt16LE(44);
const entry = elf.readUInt32LE(24);

// Doom's static 1 GiB heap lives in .bss, so the address space is large but
// sparsely used.  Keep a flat 1.09 GiB zero-filled array: Linux commits only
// pages that are actually touched.
const MEM_SIZE = 0x41000000;
const memBuf = new ArrayBuffer(MEM_SIZE);
const mem = new Uint8Array(memBuf);
const mem32 = new Uint32Array(memBuf);

let loadedEnd = 0;
for (let i = 0; i < phnum; i++) {
  const off = phoff + i * phentsize;
  if (elf.readUInt32LE(off) !== 1) continue; // PT_LOAD
  const foff = elf.readUInt32LE(off + 4);
  const vaddr = elf.readUInt32LE(off + 8);
  const filesz = elf.readUInt32LE(off + 16);
  const memsz = elf.readUInt32LE(off + 20);
  elf.copy(mem, vaddr, foff, foff + filesz);
  loadedEnd = Math.max(loadedEnd, vaddr + memsz);
}

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------
const reg = new Int32Array(32);
const freg = new Uint32Array(32);
const f32 = new Float32Array(freg.buffer);
const dscratch = new ArrayBuffer(8);
const dview = new DataView(dscratch);
const d64 = new Float64Array(dscratch);
const i64 = new BigInt64Array(dscratch);

let hi = 0, lo = 0;
let fcc0 = false;
let running = true;
let insnCount = 0;
const maxInsns = parseInt(process.env.VM_MAX_INSNS || '0', 10) || 0;

const STACK_TOP = 0x40f00000;
reg[29] = STACK_TOP | 0; // sp
reg[28] = 0x0047d090 | 0; // gp
reg[31] = 0; // ra

// ---------------------------------------------------------------------------
// Memory helpers (little endian)
// ---------------------------------------------------------------------------
function rd8(a) { return mem[a >>> 0]; }
function rd16(a) {
  a >>>= 0;
  return mem[a] | (mem[a + 1] << 8);
}
function rd32(a) {
  a >>>= 0;
  return (mem[a] | (mem[a + 1] << 8) | (mem[a + 2] << 16) | (mem[a + 3] << 24)) | 0;
}
